// One column on a phone, more from 1024dp. The scope, period and actions would sit in the TopAppBar.
MonarchDashboardGrid(
    items = sections,
    key = { it },
    itemLabel = { it },
    modifier = Modifier.fillMaxSize(),
    span = {
        when (it) {
            in wide -> MonarchDashboardGridSpan.Full
            "Needs attention", "Trend" -> MonarchDashboardGridSpan.Two
            else -> MonarchDashboardGridSpan.One
        }
    },
) { section ->
    when (section) {
        "Summary" -> Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
            MonarchText(text = {{title}}, style = MonarchTextStyle.Heading)
            MonarchText(text = {{description}}, color = MonarchTheme.colors.textMuted)
            FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                listOf({{periods.0.id}} to {{periods.0.label}}, {{periods.1.id}} to {{periods.1.label}}, {{periods.2.id}} to {{periods.2.label}}, {{periods.3.id}} to {{periods.3.label}}, {{periods.4.id}} to {{periods.4.label}}).forEach { (id, label) ->
                    MonarchButton(
                        text = label,
                        onClick = { period = id },
                        variant = if (period == id) MonarchButtonVariant.Secondary else MonarchButtonVariant.Ghost,
                        size = MonarchButtonSize.Sm,
                    )
                }
                MonarchButton(text = {{arrange}}, onClick = { editing = !editing }, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
            }
        }
        "Key figures" -> FlowRow(
            modifier = Modifier.semantics {
                isTraversalGroup = true
                contentDescription = section
            },
            maxItemsInEachRow = 2,
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        ) {
            MonarchStatCard(
                label = {{kpis.0.label}},
                value = {{kpis.0.value|double}},
                modifier = Modifier.weight(1f),
                change = MonarchMetricChange(
                    value = {{kpis.0.change.value}},
                    comparison = {{kpis.0.change.comparison}},
                    goodDirection = MonarchDeltaIndicatorGoodDirection.{{kpis.0.change.goodDirection|pascal}},
                ),
            )
            MonarchStatCard(
                label = {{kpis.1.label}},
                text = {{kpis.1.text}},
                modifier = Modifier.weight(1f),
                change = MonarchMetricChange(
                    value = {{kpis.1.change.value}},
                    comparison = {{kpis.1.change.comparison}},
                    goodDirection = MonarchDeltaIndicatorGoodDirection.{{kpis.1.change.goodDirection|pascal}},
                ),
            )
            MonarchStatCard(
                label = {{kpis.2.label}},
                value = {{kpis.2.value|double}},
                modifier = Modifier.weight(1f),
                change = MonarchMetricChange(
                    value = {{kpis.2.change.value}},
                    comparison = {{kpis.2.change.comparison}},
                ),
            )
            MonarchStatCard(
                label = {{kpis.3.label}},
                value = {{kpis.3.value|double}},
                modifier = Modifier.weight(1f),
                format = MonarchMetricFormat.{{kpis.3.format|pascal}},
            )
        }
        "Insights" -> MonarchInsightStrip(
            title = section,
            insights = listOf(
                MonarchInsight(
                    id = {{insight.id}},
                    title = {{insight.title}},
                    why = {{insight.why}},
                    origin = MonarchInsightOrigin.{{insight.origin|pascal}},
                    tone = MonarchTone.{{insight.severity|pascal}},
                    actionLabel = {{insight.action}},
                    onAction = {},
                ),
            ),
        )
        "Status" -> MonarchWidget(title = section) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = {{status.0.label}}, modifier = Modifier.weight(1f))
                    MonarchBadge(
                        text = {{status.0.state}},
                        tone = {{status.0.tone|tone}},
                        leadingIcon = { MonarchIcon(SampleIcons.Success, contentDescription = null, size = MonarchIconSize.Sm) },
                    )
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = {{status.1.label}}, modifier = Modifier.weight(1f))
                    MonarchBadge(
                        text = {{status.1.state}},
                        tone = {{status.1.tone|tone}},
                        leadingIcon = { MonarchIcon(SampleIcons.Warning, contentDescription = null, size = MonarchIconSize.Sm) },
                    )
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = {{status.2.label}}, modifier = Modifier.weight(1f))
                    MonarchBadge(
                        text = {{status.2.state}},
                        tone = {{status.2.tone|tone}},
                        leadingIcon = { MonarchIcon(SampleIcons.Success, contentDescription = null, size = MonarchIconSize.Sm) },
                    )
                }
        }
        "Needs attention" -> MonarchWidget(title = section) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = {{attention.0.label}}, modifier = Modifier.weight(1f))
                    MonarchBadge(text = {{attention.0.badge}}, tone = {{attention.0.tone|tone}})
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = {{attention.1.label}}, modifier = Modifier.weight(1f))
                    MonarchBadge(text = {{attention.1.badge}}, tone = {{attention.1.tone|tone}})
                }
        }
        "My queue" -> MonarchWidget(title = section) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = {{queue.0.label}}, modifier = Modifier.weight(1f))
                    MonarchBadge(text = {{queue.0.badge}}, tone = {{queue.0.tone|tone}})
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = {{queue.1.label}}, modifier = Modifier.weight(1f))
                    MonarchBadge(text = {{queue.1.badge}}, tone = {{queue.1.tone|tone}})
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = {{queue.2.label}}, modifier = Modifier.weight(1f))
                    MonarchBadge(text = {{queue.2.badge}}, tone = {{queue.2.tone|tone}})
                }
        }
        "Coming up" -> MonarchWidget(title = section) {
            listOf({{upcoming.0.label}} to {{upcoming.0.value}}, {{upcoming.1.label}} to {{upcoming.1.value}}).forEach { (title, value) ->
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = title, modifier = Modifier.weight(1f))
                    MonarchText(text = value, color = MonarchTheme.colors.textMuted)
                }
            }
        }
        // A chart section is the chart itself: its frame is already a card.
        "Trend" -> Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            MonarchText(text = section, style = MonarchTextStyle.Subheading)
            MonarchBarChart(
                title = {{trend.title}},
                categories = listOf({{trend.data.0.day}}, {{trend.data.1.day}}, {{trend.data.2.day}}, {{trend.data.3.day}}, {{trend.data.4.day}}),
                series = listOf(
                    MonarchBarChartSeries({{trend.series.0.key}}, {{trend.series.0.label}}, values = listOf({{trend.data.0.opened|double}}, {{trend.data.1.opened|double}}, {{trend.data.2.opened|double}}, {{trend.data.3.opened|double}}, {{trend.data.4.opened|double}})),
                    MonarchBarChartSeries({{trend.series.1.key}}, {{trend.series.1.label}}, values = listOf({{trend.data.0.solved|double}}, {{trend.data.1.solved|double}}, {{trend.data.2.solved|double}}, {{trend.data.3.solved|double}}, {{trend.data.4.solved|double}})),
                ),
                description = {{trend.description}},
                categoryTitle = {{trend.categoryLabel}},
            )
        }
        "Team load" -> MonarchWidget(title = section) {
            MonarchLeaderboard(
                entries = listOf(
                    MonarchLeaderboardEntry({{workload.entries.0.name}}, value = {{workload.entries.0.value|double}}, id = {{workload.entries.0.id}}, secondary = {{workload.entries.0.secondary}}),
                    MonarchLeaderboardEntry({{workload.entries.1.name}}, value = {{workload.entries.1.value|double}}, id = {{workload.entries.1.id}}, secondary = {{workload.entries.1.secondary}}),
                    MonarchLeaderboardEntry({{workload.entries.2.name}}, value = {{workload.entries.2.value|double}}, id = {{workload.entries.2.id}}, secondary = {{workload.entries.2.secondary}}),
                ),
                label = {{workload.valueLabel}},
                showAvatars = false,
            )
        }
        else -> MonarchWidget(title = section) {
            MonarchActivityTimeline(
                events = events,
                // A lazy list inside a grid item needs a bounded height.
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 900.dp),
                groupByDay = false,
                density = MonarchActivityTimelineDensity.Compact,
                now = now,
                timeZone = "UTC",
                labels = MonarchActivityTimelineLabels(list = "Recent activity", empty = "No activity yet"),
            )
        }
    }
}

