            MonarchText(text = "Northwind support desk", color = MonarchTheme.colors.textMuted)
            FlowRow(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
                listOf("today" to "Today", "7d" to "Last 7 days", "30d" to "Last 30 days", "quarter" to "This quarter", "custom" to "Custom").forEach { (id, label) ->
                    MonarchButton(
                        text = label,
                        onClick = { period = id },
                        variant = if (period == id) MonarchButtonVariant.Secondary else MonarchButtonVariant.Ghost,
                        size = MonarchButtonSize.Sm,
                    )
                }
                MonarchButton(text = "Arrange", onClick = { editing = !editing }, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
            }
        }
        "Key figures" -> FlowRow(
            modifier = Modifier.semantics {
                isTraversalGroup = true
                contentDescription = section
            },
            maxItemsInEachRow = 2,
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
        ) {
            MonarchStatCard(
                label = "Open tickets",
                value = 128.0,
                modifier = Modifier.weight(1f),
                change = MonarchMetricChange(
                    value = 0.12,
                    comparison = "vs last week",
                    goodDirection = MonarchDeltaIndicatorGoodDirection.Down,
                ),
            )
            MonarchStatCard(
                label = "First reply",
                text = "1h 12m",
                modifier = Modifier.weight(1f),
                change = MonarchMetricChange(
                    value = -0.08,
                    comparison = "vs last week",
                    goodDirection = MonarchDeltaIndicatorGoodDirection.Down,
                ),
            )
            MonarchStatCard(
                label = "Solved",
                value = 342.0,
                modifier = Modifier.weight(1f),
                change = MonarchMetricChange(
                    value = 0.05,
                    comparison = "vs last week",
                ),
            )
            MonarchStatCard(
                label = "Satisfaction",
                value = 0.94,
                modifier = Modifier.weight(1f),
                format = MonarchMetricFormat.Percent,
            )
        }
        "Insights" -> MonarchInsightStrip(
            title = section,
            insights = listOf(
                MonarchInsight(
                    id = "sla",
                    title = "4 tickets breach their SLA within an hour",
                    why = "All four are waiting on tier 2.",
                    origin = MonarchInsightOrigin.Rule,
                    tone = MonarchTone.Warning,
                    actionLabel = "Open tickets",
                    onAction = {},
                ),
            ),
