                    MonarchText(text = "Email", modifier = Modifier.weight(1f))
                    MonarchBadge(
                        text = "Degraded",
                        tone = MonarchTone.Warning,
                        leadingIcon = { MonarchIcon(SampleIcons.Warning, contentDescription = null, size = MonarchIconSize.Sm) },
                    )
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = "Chat", modifier = Modifier.weight(1f))
                    MonarchBadge(
                        text = "Operational",
                        tone = MonarchTone.Success,
                        leadingIcon = { MonarchIcon(SampleIcons.Success, contentDescription = null, size = MonarchIconSize.Sm) },
                    )
                }
        }
        "Needs attention" -> MonarchWidget(title = section) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = "#4821 Refund not received", modifier = Modifier.weight(1f))
                    MonarchBadge(text = "18 min left", tone = MonarchTone.Danger)
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = "#4816 Invoice shows the wrong VAT", modifier = Modifier.weight(1f))
                    MonarchBadge(text = "42 min left", tone = MonarchTone.Warning)
                }
        }
        "My queue" -> MonarchWidget(title = section) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = "#4830 Export stops after page one", modifier = Modifier.weight(1f))
                    MonarchBadge(text = "Open", tone = MonarchTone.Info)
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = "#4826 Add a second admin", modifier = Modifier.weight(1f))
                    MonarchBadge(text = "Waiting on customer", tone = MonarchTone.Neutral)
                }
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = "#4819 Card declined at renewal", modifier = Modifier.weight(1f))
                    MonarchBadge(text = "Open", tone = MonarchTone.Info)
                }
        }
        "Coming up" -> MonarchWidget(title = section) {
            listOf("Email provider maintenance" to "Tue 16 Jun, 22:00", "Weekend rota starts" to "Sat 20 Jun, 08:00").forEach { (title, value) ->
                Row(verticalAlignment = Alignment.CenterVertically) {
                    MonarchText(text = title, modifier = Modifier.weight(1f))
                    MonarchText(text = value, color = MonarchTheme.colors.textMuted)
                }
            }
        }
        // A chart section is the chart itself: its frame is already a card.
        "Trend" -> Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
            MonarchText(text = section, style = MonarchTextStyle.Subheading)
            MonarchBarChart(
                title = "Tickets opened and solved",
                categories = listOf("Mon", "Tue", "Wed", "Thu", "Fri"),
                series = listOf(
                    MonarchBarChartSeries("opened", "Opened", values = listOf(64.0, 71.0, 58.0, 66.0, 52.0)),
                    MonarchBarChartSeries("solved", "Solved", values = listOf(58.0, 66.0, 61.0, 60.0, 57.0)),
                ),
                description = "This week, by day",
                categoryTitle = "Day",
            )
        }
        "Team load" -> MonarchWidget(title = section) {
            MonarchLeaderboard(
                entries = listOf(
                    MonarchLeaderboardEntry("Priya Raman", value = 18.0, id = "priya", secondary = "Tier 1"),
                    MonarchLeaderboardEntry("Jonas Weber", value = 14.0, id = "jonas", secondary = "Tier 2"),
                    MonarchLeaderboardEntry("Amara Okafor", value = 11.0, id = "amara", secondary = "Tier 1"),
                ),
                label = "Open tickets",
                showAvatars = false,
            )
        }
        else -> MonarchWidget(title = section) {
            MonarchActivityTimeline(
                events = events,
                // A lazy list inside a grid item needs a bounded height.
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 900.dp),
                groupByDay = false,
                density = MonarchActivityTimelineDensity.Compact,
                now = now,
                timeZone = "UTC",
                labels = MonarchActivityTimelineLabels(list = "Recent activity", empty = "No activity yet"),
            )
        }
    }
